-- Ensure users table has name and avatar_url columns (used by auth callback and profile)
-- Handles schema drift: 001 used full_name; code expects name
-- Safe to run idempotently

-- Add name column if missing (migrate from full_name if it exists)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'users' AND column_name = 'name'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'users' AND column_name = 'full_name'
    ) THEN
      ALTER TABLE public.users ADD COLUMN name TEXT;
      UPDATE public.users SET name = full_name WHERE full_name IS NOT NULL;
      -- Optionally drop full_name later; keeping for now to avoid breaking any reads
    ELSE
      ALTER TABLE public.users ADD COLUMN name TEXT;
    END IF;
  END IF;
END $$

CREATE OR REPLACE FUNCTION "public"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$

-- Add appeal_count to events
ALTER TABLE events ADD COLUMN IF NOT EXISTS appeal_count integer NOT NULL DEFAULT 0;

-- Add appeal_count to clubs
ALTER TABLE clubs ADD COLUMN IF NOT EXISTS appeal_count integer NOT NULL DEFAULT 0;

-- Add club_id to notifications
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS club_id uuid REFERENCES clubs(id) ON DELETE CASCADE;

-- Create moderation_reviews table
CREATE TABLE moderation_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  target_type text NOT NULL CHECK (target_type IN ('event', 'club')),
  target_id uuid NOT NULL,
  action text NOT NULL CHECK (action IN ('rejection', 'appeal', 'approval')),
  category text CHECK (
    category IN ('inappropriate_content', 'missing_information', 'duplicate', 'policy_violation', 'incorrect_details', 'other')
  ),
  message text NOT NULL,
  author_id uuid NOT NULL,
  created_at timestamptz DEFAULT now(),
  CONSTRAINT category_required_for_rejection CHECK (
    (action = 'rejection' AND category IS NOT NULL) OR
    (action IN ('appeal', 'approval') AND category IS NULL)
  )
);

CREATE INDEX idx_moderation_reviews_target ON moderation_reviews (target_type, target_id, created_at);

ALTER TABLE moderation_reviews ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admins full access" ON moderation_reviews
  FOR ALL USING (
    EXISTS (
      SELECT 1 FROM users
      WHERE users.id = auth.uid()
      AND 'admin' = ANY(users.roles)
    )
  );

CREATE POLICY "Creators can view reviews of their items" ON moderation_reviews
  FOR SELECT USING (
    (target_type = 'event' AND EXISTS (
      SELECT 1 FROM events WHERE id = target_id AND created_by = auth.uid()
    ))
    OR
    (target_type = 'club' AND EXISTS (
      SELECT 1 FROM clubs WHERE id = target_id AND created_by = auth.uid()
    ))
  );

CREATE POLICY "Creators can appeal their items" ON moderation_reviews
  FOR INSERT WITH CHECK (
    action = 'appeal'
    AND author_id = auth.uid()
    AND (
      (target_type = 'event' AND EXISTS (
        SELECT 1 FROM events WHERE id = target_id AND created_by = auth.uid()
      ))
      OR
      (target_type = 'club' AND EXISTS (
        SELECT 1 FROM clubs WHERE id = target_id AND created_by = auth.uid()
      ))
    )
  );

ALTER TABLE events
  ADD COLUMN IF NOT EXISTS is_free BOOLEAN NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS price TEXT,
  ADD COLUMN IF NOT EXISTS rsvp_link TEXT;

COMMENT ON COLUMN events.is_free IS 'Whether the event is free to attend';
COMMENT ON COLUMN events.price IS 'Display price text (e.g. "$5", "$10-20")';
COMMENT ON COLUMN events.rsvp_link IS 'External registration/RSVP URL';

-- 1. Create experiments table (A/B testing framework)
CREATE TABLE IF NOT EXISTS public.experiments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'running', 'paused', 'completed')),
  target_metric text,
  start_date timestamptz,
  end_date timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.experiment_variants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  experiment_id uuid NOT NULL REFERENCES public.experiments(id) ON DELETE CASCADE,
  name text NOT NULL,
  config jsonb NOT NULL DEFAULT '{}',
  weight integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.experiment_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  experiment_id uuid NOT NULL REFERENCES public.experiments(id) ON DELETE CASCADE,
  variant_id uuid NOT NULL REFERENCES public.experiment_variants(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  assigned_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(experiment_id, user_id)
);

-- Indexes for experiment tables
CREATE INDEX IF NOT EXISTS idx_experiment_variants_experiment_id ON public.experiment_variants(experiment_id);
CREATE INDEX IF NOT EXISTS idx_experiment_assignments_variant_id ON public.experiment_assignments(variant_id);
CREATE INDEX IF NOT EXISTS idx_experiment_assignments_experiment_id ON public.experiment_assignments(experiment_id);

-- RLS for experiment tables (admin-only)
ALTER TABLE public.experiments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.experiment_variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.experiment_assignments ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admins can manage experiments" ON public.experiments
  FOR ALL USING (EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND 'admin' = ANY(roles)));

CREATE POLICY "Admins can manage experiment variants" ON public.experiment_variants
  FOR ALL USING (EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND 'admin' = ANY(roles)));

CREATE POLICY "Admins can manage experiment assignments" ON public.experiment_assignments
  FOR ALL USING (EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND 'admin' = ANY(roles)));

-- Users can read their own assignments
CREATE POLICY "Users can read own assignments" ON public.experiment_assignments
  FOR SELECT USING (auth.uid() = user_id);

-- 2. Update events status CHECK to include 'suspended'
ALTER TABLE public.events DROP CONSTRAINT events_status_check;
ALTER TABLE public.events ADD CONSTRAINT events_status_check
  CHECK (status IN ('pending', 'approved', 'rejected', 'suspended'));

-- 3. Update moderation_reviews action CHECK to include 'suspension'
ALTER TABLE public.moderation_reviews DROP CONSTRAINT moderation_reviews_action_check;
ALTER TABLE public.moderation_reviews ADD CONSTRAINT moderation_reviews_action_check
  CHECK (action IN ('rejection', 'appeal', 'approval', 'suspension'));

-- Update category_required_for_rejection to allow suspension without category
ALTER TABLE public.moderation_reviews DROP CONSTRAINT category_required_for_rejection;
ALTER TABLE public.moderation_reviews ADD CONSTRAINT category_required_for_rejection
  CHECK (
    ((action = 'rejection') AND (category IS NOT NULL)) OR
    ((action IN ('appeal', 'approval', 'suspension')) AND (category IS NULL))
  );

-- 4. Enable RLS on featured_clubs
ALTER TABLE public.featured_clubs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can view featured clubs" ON public.featured_clubs
  FOR SELECT USING (true);

CREATE POLICY "Admins can manage featured clubs" ON public.featured_clubs
  FOR ALL USING (EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND 'admin' = ANY(roles)));

-- 5. Add missing indexes for performance
CREATE INDEX IF NOT EXISTS idx_events_created_by ON public.events(created_by);
CREATE INDEX IF NOT EXISTS idx_clubs_created_by ON public.clubs(created_by);
CREATE INDEX IF NOT EXISTS idx_event_reports_reporter_id ON public.event_reports(reporter_id);

-- 6. Add DELETE policy for event_invites
CREATE POLICY "Users can delete own sent invites" ON public.event_invites
  FOR DELETE USING (auth.uid() = inviter_id);

CREATE POLICY "Users can delete invites sent to them" ON public.event_invites
  FOR DELETE USING (auth.uid() = invitee_id);

-- 7. Add appeal_count non-negative constraints
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'events_appeal_count_non_negative') THEN
    ALTER TABLE public.events ADD CONSTRAINT events_appeal_count_non_negative CHECK (appeal_count >= 0);
  END IF;
END $$;

ALTER TABLE public.recommendation_feedback
  ADD COLUMN IF NOT EXISTS experiment_variant_id uuid REFERENCES public.experiment_variants(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_recommendation_feedback_variant ON public.recommendation_feedback(experiment_variant_id) WHERE experiment_variant_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS feedback_request_log (
  id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       UUID        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  event_id      UUID        NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  request_type  TEXT        NOT NULL DEFAULT 'post_event' CHECK (request_type IN ('post_event', 'post_event_reminder')),
  sent_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id, event_id, request_type)
);

CREATE INDEX IF NOT EXISTS feedback_request_log_type_event_idx
  ON feedback_request_log (request_type, event_id);

CREATE INDEX IF NOT EXISTS feedback_request_log_event_idx
  ON feedback_request_log (event_id);

ALTER TABLE feedback_request_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own feedback request log"
  ON feedback_request_log
  FOR SELECT
  USING (auth.uid() = user_id);

CREATE POLICY "Service role can manage feedback request log"
  ON feedback_request_log
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

CREATE OR REPLACE FUNCTION public.send_feedback_requests()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
declare
  row record;
  cnt int;
  sent int := 0;
  skipped int := 0;
  events_processed int := 0;
begin
  -- Find events that ended 1-25 hours ago, approved and not deleted
  for row in
    select r.user_id, e.id as event_id, e.title
    from rsvps r
    join events e on e.id = r.event_id
    where e.status = 'approved'
      and e.deleted_at is null
      and r.status = 'going'
      and e.end_date between (now() - interval '25 hours') and (now() - interval '1 hour')
  loop
    -- Check if we already sent a feedback request for this user+event
    select count(*) into cnt
    from feedback_request_log
    where user_id = row.user_id
      and event_id = row.event_id
      and request_type = 'post_event';

    if cnt > 0 then
      skipped := skipped + 1;
      continue;
    end if;

    -- Create notification
    insert into notifications (user_id, event_id, type, title, message, read)
    values (
      row.user_id,
      row.event_id,
      'feedback_request',
      'How was ' || row.title || '?',
      'Share your experience — your feedback helps organizers improve future events.',
      false
    )
    on conflict do nothing;

    -- Log to prevent re-sending
    insert into feedback_request_log (user_id, event_id, request_type)
    values (row.user_id, row.event_id, 'post_event')
    on conflict do nothing;

    sent := sent + 1;
  end loop;

  -- Count distinct events processed
  select count(distinct e.id) into events_processed
  from events e
  where e.status = 'approved'
    and e.deleted_at is null
    and e.end_date between (now() - interval '25 hours') and (now() - interval '1 hour');

  return jsonb_build_object(
    'events_processed', events_processed,
    'feedback_requests_sent', sent,
    'feedback_requests_skipped', skipped,
    'checked_at', now()
  );
end;
$$;

